/// <summary>
/// Hệ số quy đổi chấm thi theo hình thức thi:
/// TH (3), VD (4) = 0.2; TN (2) và các hình thức khác = 0.1.
/// </summary>
private static decimal GetHeSoQuyDoiChamThi(DataRow row)
{
    int methodTestID = 0;

    if (row.Table.Columns.Contains("MethodTestID")
        && row["MethodTestID"] != null
        && row["MethodTestID"] != DBNull.Value)
    {
        methodTestID = Convert.ToInt32(row["MethodTestID"]);
    }

    if (methodTestID == 3 || methodTestID == 4)
        return 0.2m;

    return 0.1m;
}

